        UNION { VALUES ?root { wd:Q1229213 wd:Q21281188 wd:Q671298 wd:Q858520 wd:Q1226939 wd:Q3526714 wd:Q1268863 wd:Q5337637 wd:Q123036352 wd:Q21405405 wd:Q2881121 wd:Q24963771 wd:Q389408 wd:Q1192553 wd:Q1921825 wd:Q5439686 wd:Q105072006 wd:Q42283 wd:Q5455479 wd:Q1196156 } ?item wdt:P279 ?root }
